#requires -version 5.1
<#
.SYNOPSIS
  GBC WorkHub Aurora SessionAgent one-shot installer.

.DESCRIPTION
  - Installs the common Aurora_SessionAgent.ps1 to C:\GBCWorkHub
  - Registers an Event ID 21 scheduled task for the CURRENT Windows user
  - No PC name or TFS account input is required
  - If the PC is used by multiple Windows accounts, each user should run this installer once
#>

$ErrorActionPreference = 'Stop'

$InstallDir = 'C:\GBCWorkHub'
$AgentPath = Join-Path $InstallDir 'Aurora_SessionAgent.ps1'
$LogDir = Join-Path $InstallDir 'Logs'
$TaskName = 'GBCWorkHub_Aurora_SessionAgent'
$EventLog = 'Microsoft-Windows-TerminalServices-LocalSessionManager/Operational'
$EventId = 21

function Test-IsAdministrator {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

# C:\GBCWorkHub creation + task registration can require elevation.
if (-not (Test-IsAdministrator)) {
    if ([string]::IsNullOrWhiteSpace($PSCommandPath)) {
        throw 'Run this installer from a saved .ps1 file.'
    }

    Write-Host '[GBC WorkHub] Administrator permission is required. Opening UAC...' -ForegroundColor Yellow
    $args = '-NoProfile -ExecutionPolicy Bypass -File "{0}"' -f $PSCommandPath
    Start-Process -FilePath 'powershell.exe' -Verb RunAs -ArgumentList $args
    exit
}

try {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $userSid = $identity.User.Value
    $userName = $identity.Name

    Write-Host ''
    Write-Host '=== GBC WorkHub Aurora Agent Setup ===' -ForegroundColor Cyan
    Write-Host ("Windows user : {0}" -f $userName)
    Write-Host ("Computer     : {0}" -f $env:COMPUTERNAME)
    Write-Host ''

    # 1) Create install directories
    New-Item -ItemType Directory -Path $InstallDir -Force | Out-Null
    New-Item -ItemType Directory -Path $LogDir -Force | Out-Null

    # 2) Write the exact embedded Aurora SessionAgent
    $AgentBase64 = ''
    $bytes = [Convert]::FromBase64String($AgentBase64)
    [IO.File]::WriteAllBytes($AgentPath, $bytes)

    if (-not (Test-Path -LiteralPath $AgentPath)) {
        throw "Agent file was not created: $AgentPath"
    }

    Write-Host '[1/3] Aurora_SessionAgent.ps1 installed' -ForegroundColor Green

    # 3) Verify the event channel exists
    $null = Get-WinEvent -ListLog $EventLog -ErrorAction Stop

    # 4) Register Event ID 21 task for the current interactive user.
    #    The agent uses the interactive clipboard and the current user's TFS authentication.
    $subscription = '<QueryList><Query Id="0" Path="{0}"><Select Path="{0}">*[System[(EventID={1})]]</Select></Query></QueryList>' -f $EventLog, $EventId
    $escapedSubscription = [Security.SecurityElement]::Escape($subscription)

    $taskXml = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.4" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Description>GBC WorkHub Aurora SessionAgent - RDP session Event 21 trigger</Description>
    <Author>GBCWorkHub</Author>
  </RegistrationInfo>
  <Triggers>
    <EventTrigger>
      <Enabled>true</Enabled>
      <Subscription>$escapedSubscription</Subscription>
    </EventTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <UserId>$userSid</UserId>
      <LogonType>InteractiveToken</LogonType>
      <RunLevel>LeastPrivilege</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled>
    <Hidden>true</Hidden>
    <ExecutionTimeLimit>PT2M</ExecutionTimeLimit>
    <Priority>7</Priority>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>powershell.exe</Command>
      <Arguments>-STA -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File "C:\GBCWorkHub\Aurora_SessionAgent.ps1" connect</Arguments>
      <WorkingDirectory>C:\GBCWorkHub</WorkingDirectory>
    </Exec>
  </Actions>
</Task>
"@

    Register-ScheduledTask -TaskName $TaskName -Xml $taskXml -Force | Out-Null
    Write-Host '[2/3] Event 21 scheduled task registered' -ForegroundColor Green

    # 5) Verify
    $task = Get-ScheduledTask -TaskName $TaskName -ErrorAction Stop
    if ($task.State -eq 'Disabled') {
        Enable-ScheduledTask -TaskName $TaskName | Out-Null
        $task = Get-ScheduledTask -TaskName $TaskName
    }

    Write-Host '[3/3] Installation verified' -ForegroundColor Green
    Write-Host ''
    Write-Host 'Installed:' -ForegroundColor Cyan
    Write-Host ("  Agent : {0}" -f $AgentPath)
    Write-Host ("  Task  : {0}" -f $TaskName)
    Write-Host ("  User  : {0}" -f $userName)
    Write-Host ("  Event : {0} / ID {1}" -f $EventLog, $EventId)
    Write-Host ''
    Write-Host 'Setup completed. Reconnect to Aurora through RDP to trigger the agent.' -ForegroundColor Cyan
}
catch {
    Write-Host ''
    Write-Host ('[INSTALL FAILED] ' + $_.Exception.Message) -ForegroundColor Red
    Write-Host 'No TFS account or PC-specific parameter should be entered manually.' -ForegroundColor Yellow
    exit 1
}
